import React, { useEffect, useState } from 'react';
import { getDrivers, createDriver, updateDriver, deleteDriver } from '../api/driver.api';
import { getUsers } from '../api/user.api';

const parseCurrentUser = () => {
  try { return JSON.parse(localStorage.getItem('user')); }
  catch { return null; }
};

const DriverManagement = () => {
  const currentUser = parseCurrentUser();
  const isAdmin = currentUser?.role === 'admin';

  const [drivers, setDrivers] = useState([]);
  const [driverUsers, setDriverUsers] = useState([]);
  const [form, setForm] = useState({ user_id: '', license_number: '', phone: '' });
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchDrivers = async () => {
    try {
      const res = await getDrivers();
      setDrivers(res.data || []);
    } catch { setError('Failed to load drivers.'); }
  };

  const fetchDriverUsers = async () => {
    try {
      const res = await getUsers();
      const filtered = (res.data || []).filter(u => u.role === 'driver');
      setDriverUsers(filtered);
    } catch {}
  };

  useEffect(() => {
    fetchDrivers();
    fetchDriverUsers();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (editId) {
        await updateDriver(editId, {
          license_number: form.license_number,
          phone: form.phone,
          is_available: true
        });
      } else {
        await createDriver(form);
      }
      setForm({ user_id: '', license_number: '', phone: '' });
      setEditId(null);
      fetchDrivers();
    } catch (err) {
      setError(err.response?.data?.message || 'Operation failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (driver) => {
    setEditId(driver.id);
    setForm({ user_id: driver.user_id, license_number: driver.license_number, phone: driver.phone });
    setError('');
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this driver?')) return;
    try {
      await deleteDriver(id);
      fetchDrivers();
    } catch { setError('Delete failed.'); }
  };

  const handleToggleAvailable = async (driver) => {
    try {
      await updateDriver(driver.id, {
        license_number: driver.license_number,
        phone: driver.phone,
        is_available: !driver.is_available
      });
      fetchDrivers();
    } catch { setError('Update failed.'); }
  };

  const filtered = drivers.filter((d) => {
    const t = search.toLowerCase();
    return (
      String(d.id).includes(t) ||
      d.name?.toLowerCase().includes(t) ||
      d.email?.toLowerCase().includes(t) ||
      d.license_number?.toLowerCase().includes(t) ||
      d.phone?.includes(t)
    );
  });

  return (
    <div>
      <div className="page-title">
        <div>
          <h2>Driver Management</h2>
          <p>Track driver assignments, licenses, and availability.</p>
        </div>
      </div>

      {error && <div className="error-message" style={{ marginBottom: 16 }}>{error}</div>}

      <div className="form-card">
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>{editId ? 'Edit Driver' : 'Add New Driver'}</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              {editId ? 'Update driver license and phone.' : 'Link a driver-role user to fleet operations.'}
            </p>
          </div>
          <input
            className="filter-input"
            placeholder="Search drivers..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <form onSubmit={handleSubmit} className="form-grid">
          <div className="field-group">
            <label>Select Driver User</label>
            <select
              value={form.user_id}
              onChange={(e) => setForm({ ...form, user_id: e.target.value })}
              required={!editId}
              disabled={!!editId}
            >
              <option value="">-- Select User --</option>
              {driverUsers.map(u => (
                <option key={u.id} value={u.id}>{u.name} ({u.email})</option>
              ))}
            </select>
          </div>
          <div className="field-group">
            <label>License Number</label>
            <input
              placeholder="e.g. DL1234567890"
              value={form.license_number}
              onChange={(e) => setForm({ ...form, license_number: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Phone</label>
            <input
              placeholder="e.g. 9876543210"
              value={form.phone}
              onChange={(e) => setForm({ ...form, phone: e.target.value })}
              required
            />
          </div>
          <div className="table-actions">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Saving...' : editId ? 'Update Driver' : 'Add Driver'}
            </button>
            {editId && (
              <button type="button" className="btn btn-secondary" onClick={() => {
                setEditId(null);
                setForm({ user_id: '', license_number: '', phone: '' });
                setError('');
              }}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>

      <div className="table-card" style={{ marginTop: 20 }}>
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>Driver Roster</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              Showing {filtered.length} of {drivers.length} drivers
            </p>
          </div>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>License</th>
                <th>Phone</th>
                <th>Available</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={7} style={{ textAlign: 'center', color: 'var(--muted)' }}>No drivers found</td></tr>
              ) : filtered.map((d) => (
                <tr key={d.id}>
                  <td>{d.id}</td>
                  <td>{d.name || '—'}</td>
                  <td>{d.email || '—'}</td>
                  <td>{d.license_number}</td>
                  <td>{d.phone}</td>
                  <td>
                    <span
                      className={`status-pill ${d.is_available ? 'success' : 'danger'}`}
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleToggleAvailable(d)}
                      title="Click to toggle"
                    >
                      {d.is_available ? 'Yes' : 'No'}
                    </span>
                  </td>
                  <td className="table-actions">
                    <button className="btn btn-secondary" onClick={() => handleEdit(d)}>Edit</button>
                    {isAdmin && (
                      <button className="btn btn-danger" onClick={() => handleDelete(d.id)}>Delete</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default DriverManagement;
